{
  "stepOrder": 1,
  "name": "Tạo sách",
  "stepType": "HTTP_REQUEST",
  "config": {
    "method": "POST",
    "path": "/api/books",
    "headers": {
      "X-Tenant": "ptit"
    },
    "query_params": {
      "page": "1"
    },
    "body": {
      "title": "Clean Code",
      "author": "Martin"
    },
    "expected_status": 201,
    "assertions": [
      {
        "kind": "status",
        "equals": "201"
      },
      {
        "kind": "contains",
        "text": "Clean Code"
      },
      {
        "kind": "json_path",
        "path": "$.id"
      },
      {
        "kind": "body_equals",
        "json": {
          "id": 42,
          "title": "Clean Code"
        }
      },
      {
        "kind": "body_structure",
        "json": {
          "id": 0,
          "title": ""
        }
      },
      {
        "kind": "field_equals",
        "path": "$.title",
        "equals": "Clean Code"
      }
    ],
    "extract": [
      {
        "name": "bookId",
        "from": "response_body",
        "expression": "$.id"
      },
      {
        "name": "staticEnv",
        "from": "response_body",
        "expression": "$.env"
      }
    ]
  },
  "weight": 2,
  "timeoutMs": 30000,
  "required": true,
  "description": "Covers every assertion kind (lowercase-only) + both extract forms"
}

